  required_version = ">= 1.8.2"
}

resource "aws_wafv2_web_acl" "default" {
  name  = "default-CLOUDFRONT-web-acl"
  scope = "CLOUDFRONT"

  default_action {
    block {}
  }

  rule {
    name     = "rule-CLOUDFRONT-AWSManagedRulesCommonRuleSet"
    priority = 1

    override_action {
      none {}
    }

    statement {
      managed_rule_group_statement {
        name        = "AWSManagedRulesCommonRuleSet"
        vendor_name = "AWS"
      }
    }

    visibility_config {
      cloudwatch_metrics_enabled = true
      metric_name                = "rule-CLOUDFRONT-AWSManagedRulesCommonRuleSet"
      sampled_requests_enabled   = true
    }
  }

  rule {
    name     = "AWS-AWSManagedRulesKnownBadInputsRuleSet"
    priority = 2

    override_action {
      none {}
    }

    statement {
      managed_rule_group_statement {
        name        = "AWSManagedRulesKnownBadInputsRuleSet"
        vendor_name = "AWS"
      }
    }

    visibility_config {
      cloudwatch_metrics_enabled = true
      metric_name                = "rule-CLOUDFRONT-AWSManagedRulesKnownBadInputsRuleSet"
      sampled_requests_enabled   = true
    }
  }

  dynamic "rule" {
    # emulate Terraform parser placing placeholder integer for for_each
    for_each = [1]

    content {
      name     = "rule-CLOUDFRONT-ip-allowlist"
      priority = 8

      action {
        allow {}
      }

      statement {
        or_statement {
          statement {
            ip_set_reference_statement {
              arn = "arn:aws:wafv2:region:acct:ipset/allow/1"
            }
          }
          statement {
            ip_set_reference_statement {
              arn = "arn:aws:wafv2:region:acct:ipset/gh/1"
            }
          }
        }
      }

      visibility_config {
        cloudwatch_metrics_enabled = true
        metric_name                = "rule-CLOUDFRONT-ip-allowlist"
        sampled_requests_enabled   = true
      }
    }
  }

  dynamic "rule" {
    for_each = [1]

    content {
      name     = "rule-CLOUDFRONT-review-token-check"
      priority = 30

      action {
        allow {}
      }

      statement {
        byte_match_statement {
          positional_constraint = "EXACTLY"
          search_string         = "token"

          field_to_match {
            single_header {
              name = "review-token"
            }
          }

          text_transformation {
            priority = 1
            type     = "NONE"
          }
        }
      }

      visibility_config {
        cloudwatch_metrics_enabled = true
        metric_name                = "rule-CLOUDFRONT-review-token-check"
        sampled_requests_enabled   = true
      }
    }
  }

  visibility_config {
    cloudwatch_metrics_enabled = true
    metric_name                = "CLOUDFRONT-web-acl"
    sampled_requests_enabled   = true
  }
}
